1	/**
2	 * Declared migration target cells for an Angular CLI workspace, and the
3	 * dependency alignment an upgrade to one of them performs.
4	 *
5	 * A cell is a named tuple of (Angular line, official builder, Node line,
6	 * TypeScript line). Nothing here is application specific: the tables describe
7	 * the Angular ecosystem, keyed by package name and package family, and are
8	 * applied to whatever manifest they are handed.
9	 *
10	 * The version strings are *ranges written into the manifest*, exactly as the
11	 * official upgrade path writes them. They are a request to the package
12	 * manager, not a claim that any particular patch release was resolved: this
13	 * module performs no installation and observes no registry.
14	 */
15	
16	export type AngularVersionRanges = Readonly<Record<string, string>>;
17	
18	export type AngularTargetCell = Readonly<{
19		/** Stable identifier used in migration records. */
20		id: string;
21		/** The Angular major line this cell targets. */
22		angularLine: string;
23		/** The official builder the application is expected to build with. */
24		builder: string;
25		/** The Node line the target cell is declared against. */
26		nodeLine: string;
27		/** The TypeScript range the Angular line accepts. */
28		typescriptRange: string;
29		/** Version range per exact package name. Wins over {@link families}. */
30		packages: AngularVersionRanges;
31		/** Version range per package name prefix, longest prefix wins. */
32		families: AngularVersionRanges;
33		/**
34		 * The unit-test toolchain the Angular line's own schematics generate, keyed
35		 * by exact package name.
36		 *
37		 * This is a separate table from {@link packages} because it answers a
38		 * different question. `packages` says what the build cell needs; this says
39		 * what the line's `ng new` output pairs with that build cell. A package named
40		 * here is aligned; a test-toolchain package the line does not generate is
41		 * left at its era range and reported, because choosing a version for it is a
42		 * decision about the application's test cell rather than a fact about the
43		 * Angular line.
44		 */
45		testPackages: AngularVersionRanges;
46		/** Why this cell and not a newer one. Recorded verbatim in evidence. */
47		rationale: readonly string[];
48		/** What adopting this cell does not establish. */
49		nonclaims: readonly string[];
50	}>;
