52	/**
53	 * Angular 16 with the `browser` builder.
54	 *
55	 * Chosen over a newer line for reasons that are recorded rather than implied:
56	 * Angular 16 is the newest line whose published Node support range includes a
57	 * Node runtime this host actually carries natively (Node 16.20.2 sits inside
58	 * Angular 16's `^16.14.0 || ^18.10.0`), and it is the newest line on which
59	 * `@angular-devkit/build-angular:browser` — the builder the era workspace
60	 * already declares — is still the mainstream application builder, so the
61	 * builder identity is carried across the hop instead of being swapped for the
62	 * `application` builder at the same time as the framework version.
63	 */
64	export const ANGULAR_16_BROWSER_CELL: AngularTargetCell = Object.freeze({
65		id: 'angular-16-browser-builder',
66		angularLine: '16.2',
67		builder: '@angular-devkit/build-angular:browser',
68		nodeLine: '16.20.2',
69		typescriptRange: '~5.1.3',
70		packages: Object.freeze({
71			rxjs: '~7.8.0',
72			'zone.js': '~0.13.0',
73			tslib: '^2.3.0',
74			typescript: '~5.1.3',
75		}),
76		families: Object.freeze({
77			'@angular/': '^16.2.0',
78			'@angular-devkit/': '^16.2.0',
79			'@schematics/': '^16.2.0',
80			'@ngrx/': '^16.3.0',
81			'@angular-eslint/': '^16.1.0',
82		}),
83		testPackages: Object.freeze({
84			'@types/jasmine': '~4.3.0',
85			'jasmine-core': '~4.6.0',
86			karma: '~6.4.0',
87			'karma-chrome-launcher': '~3.2.0',
88			'karma-coverage': '~2.2.0',
89			'karma-jasmine': '~5.1.0',
90			'karma-jasmine-html-reporter': '~2.1.0',
91		}),
92		rationale: Object.freeze([
93			'Angular 16 accepts Node ^16.14.0 || ^18.10.0; this host carries a native Node 16.20.2, which is inside that range.',
94			'The `browser` builder the era workspace already declares is still the mainstream application builder on the Angular 16 line, so the builder identity survives the hop unchanged.',
95			'A newer line was not declared because it would pair an unverified Node line with a builder swap in the same step, and neither could be evidenced here.',
96			'@angular-eslint is versioned in lockstep with the Angular major it lints — its 16.x line is the one published for Angular 16 — and its schematics package pins a peer range on the matching @angular/cli major. An era @angular-eslint left in place makes the closure unresolvable, so the family is aligned with the framework rather than left behind.',
97			'The test toolchain is declared as the versions this line’s own schematics generate. Leaving it at its era ranges is not a neutral choice: an era jasmine pinned below what a floating karma reporter range now demands makes the dependency closure unresolvable, so the install that the build cell needs cannot happen at all.',
