110	export type PackageManifest = Readonly<Record<string, unknown>>;
111	
112	export type DependencyChange = Readonly<{
113		field: 'dependencies' | 'devDependencies';
114		name: string;
115		from: string;
116		to: string | null;
117		reason: string;
118	}>;
