120	export type ManifestAlignment = Readonly<{
121		manifest: PackageManifest;
122		changes: readonly DependencyChange[];
123		unhandled: readonly string[];
124	}>;
125	
126	const DEPENDENCY_FIELDS = ['dependencies', 'devDependencies'] as const;
127	
128	/**
129	 * Packages that exist only to serve a builder the modern devkit no longer
130	 * ships. They are removed together with the target that used them, never on
131	 * their own — the workspace migration decides whether the target is dropped
132	 * and passes the released package names here.
133	 */
134	export const REMOVED_BUILDER_PACKAGES: Readonly<Record<string, readonly string[]>> = Object.freeze({
135		'@angular-devkit/build-angular:tslint': Object.freeze(['tslint', 'codelyzer']),
136		'@angular-devkit/build-angular:protractor': Object.freeze([
137			'protractor',
138			'jasmine-spec-reporter',
139			'@types/jasminewd2',
140		]),
141	});
142	
143	export function compareStrings(left: string, right: string): number {
144		if (left === right) return 0;
145		return left < right ? -1 : 1;
146	}
147	
148	/** The range the cell asks for, or null when the cell says nothing about it. */
149	export function alignedVersionRange(name: string, cell: AngularTargetCell): string | null {
150		const exact = cell.packages[name];
151		if (exact !== undefined) return exact;
152		const test = cell.testPackages[name];
153		if (test !== undefined) return test;
154		let match: string | null = null;
155		let matchedPrefix = '';
156		for (const [prefix, range] of Object.entries(cell.families))
157			if (name.startsWith(prefix) && prefix.length > matchedPrefix.length) {
158				match = range;
159				matchedPrefix = prefix;
160			}
161		return match;
162	}
163	
164	function dependencyRecord(manifest: PackageManifest, field: string): Record<string, string> {
165		const value = manifest[field];
166		if (value === undefined) return {};
167		if (typeof value !== 'object' || value === null || Array.isArray(value))
168			throw new Error(`Angular manifest alignment: "${field}" is not an object`);
169		const entries: Record<string, string> = {};
170		for (const [name, range] of Object.entries(value as Record<string, unknown>)) {
171			if (typeof range !== 'string')
172				throw new Error(`Angular manifest alignment: "${field}.${name}" is not a string`);
173			entries[name] = range;
174		}
175		return entries;
176	}
177	
178	/**
179	 * Rewrite a manifest's Angular-ecosystem dependency ranges onto the declared
180	 * cell, and drop packages released by builders the workspace migration removed.
181	 *
182	 * What this does not do, and reports instead of hiding: a package outside the
183	 * cell's tables is left exactly as it is. The test toolchain is aligned only as
184	 * far as the cell's `testPackages` table reaches — the packages the line's own
185	 * schematics generate — and a karma or jasmine package outside that set is left
186	 * at its era range and reported as unhandled, because picking a version for it
187	 * is a decision about the application's test cell rather than a fact about the
188	 * Angular line.
189	 */
190	export function alignAngularPackageManifest(
191		manifest: PackageManifest,
192		cell: AngularTargetCell,
193		removedPackages: readonly string[] = [],
194	): ManifestAlignment {
195		const removed = new Set(removedPackages);
196		const changes: DependencyChange[] = [];
197		const unhandled: string[] = [];
198		const next: Record<string, unknown> = { ...manifest };
199		for (const field of DEPENDENCY_FIELDS) {
200			if (manifest[field] === undefined) continue;
201			const current = dependencyRecord(manifest, field);
202			const updated: Record<string, string> = {};
203			for (const name of Object.keys(current).sort(compareStrings)) {
204				const from = current[name] as string;
205				if (removed.has(name)) {
206					changes.push({
207						field,
208						name,
209						from,
210						to: null,
211						reason: 'released by a builder target the workspace migration removed',
212					});
213					continue;
214				}
215				const range = alignedVersionRange(name, cell);
216				if (range === null) {
217					updated[name] = from;
218					if (TEST_TOOLCHAIN_PREFIXES.some((prefix) => name.startsWith(prefix)))
219						unhandled.push(
220							`${field}.${name} is coupled to the Angular test cell but is not part of the ` +
221								`toolchain ${cell.id} generates, so it was left at its era range`,
222						);
223					continue;
224				}
225				updated[name] = range;
226				if (range !== from)
227					changes.push({
228						field,
229						name,
230						from,
231						to: range,
232						reason:
233							cell.testPackages[name] === undefined
234								? `aligned to ${cell.id}`
235								: `aligned to the test toolchain ${cell.id} generates`,
236					});
237			}
238			next[field] = updated;
239		}
240		return Object.freeze({
241			manifest: Object.freeze(next),
242			changes: Object.freeze(changes),
243			unhandled: Object.freeze(unhandled.sort(compareStrings)),
244		});
245	}
246	
247	const TEST_TOOLCHAIN_PREFIXES: readonly string[] = Object.freeze([
248		'karma',
249		'jasmine',
250		'@types/jasmine',
251	]);
