1	/**
2	 * Angular CLI workspace and TypeScript configuration migration.
3	 *
4	 * The shapes handled here are the ones the Angular CLI itself defines and the
5	 * ones the modern `@angular-devkit/build-angular` schema no longer accepts. No
6	 * capability branches on a project name, an application name or a source
7	 * string: every project in `angular.json` is walked, whatever it is called.
8	 *
9	 * Both entry points parse strict JSON. A configuration carrying comments
10	 * (JSONC, which the CLI also accepts) is refused with a diagnosable error
11	 * rather than silently reserialized, because rewriting it would delete the
12	 * comments without saying so.
13	 */
14	
15	import { REMOVED_BUILDER_PACKAGES, compareStrings } from './angular-target-cell.ts';
16	import type { AngularTargetCell } from './angular-target-cell.ts';
17	import {
18		WRAPPER_BUILDER_REPLACEMENTS,
19		WRAPPER_ONLY_OPTIONS,
20		analyzeCustomWebpackFragment,
21		builderPackageOf,
22		type WebpackFragmentAnalysis,
23	} from './custom-webpack-absorption.ts';
24	
25	export type ConfigChange = Readonly<{ path: string; from: string | null; to: string | null }>;
26	
27	export type WorkspaceMigration = Readonly<{
28		config: string;
29		changes: readonly ConfigChange[];
30		removedPackages: readonly string[];
31		unhandled: readonly string[];
32		/**
33		 * Webpack fragments that are no longer referenced by any target, because the
34		 * wrapper builder that read them was absorbed back into the official builder.
35		 */
36		absorbedFragments: readonly WebpackFragmentAnalysis[];
37	}>;
38	
39	/**
40	 * Webpack fragments a wrapper builder may reference, keyed by the path the
41	 * workspace writes for them. A referenced fragment that is not supplied here
42	 * cannot be read, and an unread fragment is never absorbed.
43	 */
44	export type WebpackFragmentSources = Readonly<Record<string, string>>;
45	
46	type JsonObject = Record<string, unknown>;
47	
48	/**
49	 * Builder options the modern devkit schema no longer accepts. A build fails
50	 * outright on an unknown option, so leaving one in place is not a cosmetic
51	 * defect.
52	 *
53	 * `extractCss` was removed once CSS extraction became unconditional in
54	 * production; `es5BrowserSupport` and `showCircularDependencies` went with the
55	 * differential-loading and webpack-plugin surfaces they configured;
56	 * `experimentalRollupPass` and `lazyModules` were experimental options the
57	 * devkit dropped.
58	 */
59	export const REMOVED_BUILDER_OPTIONS: readonly string[] = Object.freeze([
60		'es5BrowserSupport',
61		'experimentalRollupPass',
62		'extractCss',
63		'lazyModules',
64		'showCircularDependencies',
65	]);
66	
67	/**
68	 * Builders the modern devkit no longer ships at all. The target that uses one
69	 * cannot be carried across the hop: it is removed, and the packages it existed
70	 * to run are reported so the manifest alignment can drop them too. Replacing
71	 * the capability the target provided (a linter, an end-to-end runner) is a
72	 * decision about the project, not a mechanical rewrite, so this capability
73	 * makes no attempt at one and says so.
74	 */
75	export const REMOVED_BUILDERS: readonly string[] = Object.freeze(
76		Object.keys(REMOVED_BUILDER_PACKAGES).sort(compareStrings),
77	);
78	
79	/** Builders this capability recognises as still present on a modern line. */
80	export const CARRIED_BUILDERS: readonly string[] = Object.freeze([
81		'@angular-devkit/build-angular:browser',
82		'@angular-devkit/build-angular:dev-server',
83		'@angular-devkit/build-angular:extract-i18n',
84		'@angular-devkit/build-angular:karma',
85		'@angular-devkit/build-angular:ng-packagr',
86		'@angular-devkit/build-angular:server',
87	]);
88	
89	/**
90	 * True when the document carries a `//` or `/* … *\/` comment outside a string
91	 * literal. String contents are skipped, because a JSON string legitimately
92	 * holds both sequences — a glob such as `**\/node_modules/**` and a URL both
93	 * do — and treating those as comments would refuse a strict JSON document.
94	 */
95	export function carriesJsonComment(source: string): boolean {
96		let inString = false;
97		for (let index = 0; index < source.length; index += 1) {
98			const character = source[index];
99			if (inString) {
100				if (character === '\\') index += 1;
101				else if (character === '"') inString = false;
102				continue;
103			}
104			if (character === '"') {
105				inString = true;
106				continue;
107			}
108			if (character !== '/') continue;
109			const next = source[index + 1];
110			if (next === '/' || next === '*') return true;
111		}
112		return false;
113	}
114	
115	function parseStrictJson(source: string, kind: string): JsonObject {
116		if (carriesJsonComment(source))
117			throw new Error(
118				`Angular ${kind} migration: the configuration appears to carry comments. ` +
119					'This capability rewrites strict JSON only; a JSONC configuration would lose ' +
120					'its comments silently, so it is refused instead.',
121			);
122		const parsed: unknown = JSON.parse(source);
123		if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed))
124			throw new Error(`Angular ${kind} migration: the configuration is not a JSON object`);
125		return parsed as JsonObject;
126	}
127	
128	function serialize(value: unknown): string {
129		return `${JSON.stringify(value, null, 2)}\n`;
130	}
131	
132	function objectAt(value: unknown): JsonObject | null {
133		return typeof value === 'object' && value !== null && !Array.isArray(value)
134			? (value as JsonObject)
135			: null;
136	}
137	
138	/** `./webpack.config.js` and `webpack.config.js` name the same file. */
139	export function normalizeFragmentPath(value: string): string {
140		return value.startsWith('./') ? value.slice(2) : value;
141	}
142	
143	/** The fragment a wrapper target references, or null when it references none. */
144	function fragmentPathOf(target: JsonObject): string | null {
145		const options = objectAt(target['options']);
146		const declared = options === null ? undefined : objectAt(options['customWebpackConfig']);
147		const path = declared?.['path'];
148		return typeof path === 'string' ? normalizeFragmentPath(path) : null;
149	}
150	
151	type WrapperAbsorption = Readonly<{
152		/** True when every fragment any wrapper target references can be absorbed. */
153		absorbed: boolean;
154		analyses: readonly WebpackFragmentAnalysis[];
155		blockers: readonly string[];
156		/** Wrapper packages released once every one of their targets is absorbed. */
157		releasedPackages: readonly string[];
158	}>;
159	
160	/**
161	 * Decide, for the whole workspace at once, whether the wrapper builders can be
162	 * absorbed back into the official ones.
163	 *
164	 * The decision is workspace-wide rather than per target because the wrapper is
165	 * one dependency serving all of them, and because a wrapper target that names no
166	 * fragment of its own — a `dev-server` reading its browser target's — is only
167	 * absorbable if the fragment that target names is. Absorbing some targets and
168	 * not others would leave the package installed and the build half-migrated, so
169	 * one unreadable fragment refuses the lot.
170	 */
171	function planWrapperAbsorption(
172		projects: JsonObject,
173		fragments: WebpackFragmentSources,
174	): WrapperAbsorption {
175		const analyses = new Map<string, WebpackFragmentAnalysis>();
176		const blockers: string[] = [];
177		const releasedPackages = new Set<string>();
178		let sawWrapper = false;
179		for (const projectValue of Object.values(projects)) {
180			const project = objectAt(projectValue);
181			if (project === null) continue;
182			const architect = objectAt(project['architect']) ?? objectAt(project['targets']);
183			if (architect === null) continue;
184			for (const targetValue of Object.values(architect)) {
185				const target = objectAt(targetValue);
186				const builder = target === null ? null : target['builder'];
187				if (typeof builder !== 'string') continue;
188				const official = WRAPPER_BUILDER_REPLACEMENTS[builder];
189				if (official === undefined) continue;
190				sawWrapper = true;
191				const released = builderPackageOf(builder);
192				if (released !== null) releasedPackages.add(released);
193				const fragmentPath = target === null ? null : fragmentPathOf(target);
194				if (fragmentPath === null) continue;
195				if (analyses.has(fragmentPath)) continue;
196				const source = fragments[fragmentPath] ?? fragments[`./${fragmentPath}`];
197				if (source === undefined) {
198					blockers.push(
199						`${fragmentPath} is referenced by ${builder} but its contents were not supplied, ` +
200							'so what it adds to the build cannot be read and the wrapper was left in place',
201					);
202					continue;
203				}
204				analyses.set(fragmentPath, analyzeCustomWebpackFragment(fragmentPath, source, official));
205			}
206		}
207		for (const analysis of analyses.values())
208			if (!analysis.absorbable)
209				for (const blocker of analysis.blockers)
210					blockers.push(`${analysis.path}: ${blocker}`);
211		return Object.freeze({
212			absorbed: sawWrapper && blockers.length === 0,
213			analyses: Object.freeze([...analyses.values()]),
214			blockers: Object.freeze(blockers),
215			releasedPackages: Object.freeze([...releasedPackages].sort(compareStrings)),
216		});
217	}
218	
219	function migrateBuilderOptions(
220		options: JsonObject,
221		prefix: string,
222		changes: ConfigChange[],
223		wrapperAbsorbed: boolean,
224	): JsonObject {
225		const next: JsonObject = {};
226		for (const [key, value] of Object.entries(options)) {
227			if (wrapperAbsorbed && WRAPPER_ONLY_OPTIONS.includes(key)) {
228				changes.push({ path: `${prefix}.${key}`, from: JSON.stringify(value), to: null });
229				continue;
230			}
231			if (REMOVED_BUILDER_OPTIONS.includes(key)) {
232				changes.push({ path: `${prefix}.${key}`, from: JSON.stringify(value), to: null });
233				continue;
234			}
235			if (key === 'polyfills' && typeof value === 'string') {
236				next[key] = [value];
237				changes.push({
238					path: `${prefix}.polyfills`,
239					from: JSON.stringify(value),
240					to: JSON.stringify([value]),
241				});
242				continue;
243			}
244			next[key] = value;
245		}
246		return next;
247	}
248	
249	/**
250	 * Migrate an `angular.json` workspace onto the declared cell.
251	 *
252	 * Three mechanical changes, each one a shape the modern schema rejects: the
253	 * workspace-level `defaultProject` key, builder options the devkit removed
254	 * (in a target's `options` and in every named configuration), and the
255	 * `polyfills` option's string form, which became an array of entry points.
256	 * Targets whose builder no longer exists are removed and reported.
257	 */
258	export function migrateAngularWorkspace(
259		source: string,
260		cell: AngularTargetCell,
261		fragments: WebpackFragmentSources = {},
262	): WorkspaceMigration {
263		const workspace = parseStrictJson(source, 'workspace');
264		const changes: ConfigChange[] = [];
265		const removedPackages = new Set<string>();
266		const unhandled: string[] = [];
267		const next: JsonObject = {};
268		for (const [key, value] of Object.entries(workspace)) {
269			if (key === 'defaultProject') {
270				changes.push({ path: 'defaultProject', from: JSON.stringify(value), to: null });
271				continue;
272			}
273			if (key === 'cli') {
274				const cli = objectAt(value);
275				if (cli !== null && 'defaultCollection' in cli) {
276					const { defaultCollection, ...rest } = cli;
277					const collections =
278						typeof defaultCollection === 'string' ? [defaultCollection] : defaultCollection;
279					next[key] = { ...rest, schematicCollections: collections };
280					changes.push({
281						path: 'cli.defaultCollection',
282						from: JSON.stringify(defaultCollection),
283						to: null,
284					});
285					changes.push({
286						path: 'cli.schematicCollections',
287						from: null,
288						to: JSON.stringify(collections),
289					});
290					continue;
291				}
292			}
293			next[key] = value;
294		}
295		const projects = objectAt(next['projects']);
296		const absorption =
297			projects === null
298				? { absorbed: false, analyses: [], blockers: [], releasedPackages: [] }
299				: planWrapperAbsorption(projects, fragments);
300		unhandled.push(...absorption.blockers);
301		if (absorption.absorbed) for (const name of absorption.releasedPackages) removedPackages.add(name);
302		if (projects !== null) {
303			const migratedProjects: JsonObject = {};
304			for (const [projectName, projectValue] of Object.entries(projects)) {
305				const project = objectAt(projectValue);
306				if (project === null) {
307					migratedProjects[projectName] = projectValue;
308					continue;
309				}
310				const architect = objectAt(project['architect']) ?? objectAt(project['targets']);
311				if (architect === null) {
312					migratedProjects[projectName] = project;
313					continue;
314				}
315				const architectKey = objectAt(project['architect']) === null ? 'targets' : 'architect';
316				const migratedTargets: JsonObject = {};
317				for (const [targetName, targetValue] of Object.entries(architect)) {
318					const target = objectAt(targetValue);
319					let builder = target === null ? null : target['builder'];
320					const targetPath = `projects.${projectName}.${architectKey}.${targetName}`;
321					if (
322						absorption.absorbed &&
323						typeof builder === 'string' &&
324						WRAPPER_BUILDER_REPLACEMENTS[builder] !== undefined
325					) {
326						const official = WRAPPER_BUILDER_REPLACEMENTS[builder] as string;
327						changes.push({ path: `${targetPath}.builder`, from: builder, to: official });
328						builder = official;
329					}
330					if (typeof builder === 'string' && REMOVED_BUILDERS.includes(builder)) {
331						changes.push({ path: targetPath, from: builder, to: null });
332						for (const name of REMOVED_BUILDER_PACKAGES[builder] ?? [])
333							removedPackages.add(name);
334						unhandled.push(
335							`${targetPath} used ${builder}, which the ${cell.angularLine} devkit does not ship; ` +
336								'the target was removed and no replacement capability was chosen for it',
337						);
338						continue;
339					}
340					if (typeof builder === 'string' && !CARRIED_BUILDERS.includes(builder)) {
341						unhandled.push(
342							`${targetPath} uses ${builder}, which this capability does not recognise; ` +
343								'its options were left untouched',
344						);
345						migratedTargets[targetName] = targetValue;
346						continue;
347					}
348					if (target === null) {
349						migratedTargets[targetName] = targetValue;
350						continue;
351					}
352					const migratedTarget: JsonObject = { ...target, builder };
353					const options = objectAt(target['options']);
354					if (options !== null)
355						migratedTarget['options'] = migrateBuilderOptions(
356							options,
357							`${targetPath}.options`,
358							changes,
359							absorption.absorbed,
360						);
361					const configurations = objectAt(target['configurations']);
362					if (configurations !== null) {
363						const migratedConfigurations: JsonObject = {};
364						for (const [name, value] of Object.entries(configurations)) {
365							const configuration = objectAt(value);
366							migratedConfigurations[name] =
367								configuration === null
368									? value
369									: migrateBuilderOptions(
370											configuration,
371											`${targetPath}.configurations.${name}`,
372											changes,
373											absorption.absorbed,
374										);
375						}
376						migratedTarget['configurations'] = migratedConfigurations;
377					}
378					migratedTargets[targetName] = migratedTarget;
379				}
380				migratedProjects[projectName] = { ...project, [architectKey]: migratedTargets };
381			}
382			next['projects'] = migratedProjects;
383		}
384		return Object.freeze({
385			config: serialize(next),
386			changes: Object.freeze(changes),
387			removedPackages: Object.freeze([...removedPackages].sort(compareStrings)),
388			unhandled: Object.freeze(unhandled),
389			absorbedFragments: Object.freeze(absorption.absorbed ? absorption.analyses : []),
390		});
391	}
392	
393	export type TsConfigMigration = Readonly<{
394		config: string;
395		changes: readonly ConfigChange[];
396		unhandled: readonly string[];
397	}>;
398	
399	/**
400	 * Migrate a workspace `tsconfig.json` onto the declared cell.
401	 *
402	 * The Angular compiler on a modern line emits ES2022 output and requires
403	 * `useDefineForClassFields: false` at that target, because TypeScript's
404	 * standards-compliant class-field semantics would otherwise overwrite the
405	 * fields Angular's decorators initialise. `enableIvy` is removed: Ivy is the
406	 * only compiler left, and the option is no longer read.
407	 */
408	export function migrateAngularTsConfig(source: string, cell: AngularTargetCell): TsConfigMigration {
409		const config = parseStrictJson(source, 'tsconfig');
410		const changes: ConfigChange[] = [];
411		const unhandled: string[] = [];
412		const next: JsonObject = { ...config };
413		const compilerOptions = objectAt(config['compilerOptions']);
414		if (compilerOptions === null) {
415			unhandled.push('the tsconfig declares no compilerOptions; nothing was aligned');
416			return Object.freeze({
417				config: serialize(next),
418				changes: Object.freeze(changes),
419				unhandled: Object.freeze(unhandled),
420			});
421		}
422		const migrated: JsonObject = { ...compilerOptions };
423		for (const key of ['target', 'module'] as const) {
424			const from = compilerOptions[key];
425			if (from === 'ES2022') continue;
426			migrated[key] = 'ES2022';
427			changes.push({
428				path: `compilerOptions.${key}`,
429				from: from === undefined ? null : JSON.stringify(from),
430				to: '"ES2022"',
431			});
432		}
433		if (compilerOptions['useDefineForClassFields'] !== false) {
434			migrated['useDefineForClassFields'] = false;
435			changes.push({
436				path: 'compilerOptions.useDefineForClassFields',
437				from:
438					compilerOptions['useDefineForClassFields'] === undefined
439						? null
440						: JSON.stringify(compilerOptions['useDefineForClassFields']),
441				to: 'false',
442			});
443		}
444		next['compilerOptions'] = migrated;
445		const angularCompilerOptions = objectAt(config['angularCompilerOptions']);
446		if (angularCompilerOptions !== null && 'enableIvy' in angularCompilerOptions) {
447			const { enableIvy, ...rest } = angularCompilerOptions;
448			next['angularCompilerOptions'] = rest;
449			changes.push({
450				path: 'angularCompilerOptions.enableIvy',
451				from: JSON.stringify(enableIvy),
452				to: null,
453			});
454		}
455		unhandled.push(
456			`compilerOptions.lib was left as declared; the ${cell.angularLine} line does not require a specific lib set ` +
457				'and narrowing one could remove a type surface the application relies on',
458		);
459		return Object.freeze({
460			config: serialize(next),
461			changes: Object.freeze(changes),
462			unhandled: Object.freeze(unhandled),
463		});
464	}
