// Consented registry metadata reads. Metadata only: no tarball is fetched.
// Consent: VL-LEGACY-CORPUS-2026-08-10
const names = process.argv.slice(2);
const ACCEPT = 'application/vnd.npm.install-v1+json';
for (const name of names) {
	const url = `https://registry.npmjs.org/${name.replace('/', '%2f')}`;
	const response = await fetch(url, { headers: { accept: ACCEPT } });
	if (!response.ok) {
		console.log(`${name}\tHTTP ${response.status}\t${url}`);
		continue;
	}
	const doc = await response.json();
	const versions = Object.keys(doc.versions ?? {});
	const rows = [];
	for (const version of versions) {
		const meta = doc.versions[version];
		const peers = meta.peerDependencies ?? {};
		const angular = Object.entries(peers)
			.filter(([key]) => key.startsWith('@angular/'))
			.map(([key, range]) => `${key}@${range}`)
			.join(' ');
		rows.push({ version, angular, deprecated: meta.deprecated !== undefined });
	}
	console.log(`\n### ${name}  (${url})`);
	console.log(`latest: ${doc['dist-tags']?.latest}`);
	const filter = process.env.FILTER;
	for (const row of rows) {
		if (filter && !new RegExp(filter).test(row.version)) continue;
		if (row.angular === '' && filter === undefined) continue;
		console.log(`  ${row.version}\t${row.angular}${row.deprecated ? '\t[DEPRECATED]' : ''}`);
	}
}

