	const url = `https://registry.npmjs.org/${name.replace('/', '%2f')}`;
	const doc = await (await fetch(url, { headers: { accept: 'application/vnd.npm.install-v1+json' } })).json();
	const versions = Object.keys(doc.versions ?? {});
	const stable = versions.filter((v) => !v.includes('-'));
	const majors = new Map();
	for (const v of stable) { const m = v.split('.')[0]; majors.set(m, v); }
	console.log(`\n### ${name} (${url})`);
	console.log('  dist-tags:', JSON.stringify(doc['dist-tags']));
	console.log('  last stable per major:', [...majors.entries()].map(([m, v]) => v).join(' '));
	const last = doc.versions[stable[stable.length - 1]];
	console.log('  count:', versions.length);
}
