content.content:
1	/**
2	 * The composed Angular CLI era migration: workspace configuration, TypeScript
3	 * configuration, package manifest and application source, lifted onto one
4	 * declared target cell and reported as a single itemised changeset.
5	 *
6	 * The changeset is the product. It records, per file, the bytes before and
7	 * after as digests and the individual changes that produced them, and it
8	 * separates application files from workspace files so that a count of changed
9	 * application files means what it says: source the application owns, changed by
10	 * a transform, not a version number edited in a manifest.
11	 */
12	
13	import { createHash } from 'node:crypto';
14	import {
15		alignAngularPackageManifest,
16		compareStrings,
17		type AngularTargetCell,
18		type DependencyChange,
19	} from './angular-target-cell.ts';
20	import { migrateAngularSourceModule, type SourceChange } from './angular-source-migration.ts';
21	import {
22		migrateNgrxEffectDecorators,
23		type NgrxEffectChange,
24	} from './ngrx-effects-migration.ts';
25	import {
26		migrateAngularTsConfig,
27		migrateAngularWorkspace,
28		normalizeFragmentPath,
29		type ConfigChange,
30	} from './angular-workspace-migration.ts';
31	
32	export type WorkspaceFile = Readonly<{ path: string; source: string }>;
33	
34	export type AngularMigrationInput = Readonly<{
35		packageManifest: WorkspaceFile;
36		workspaceConfig: WorkspaceFile;
37		tsConfig: WorkspaceFile;
38		/** Application source modules, as read from the workspace. */
39		sourceModules: readonly WorkspaceFile[];
40		/**
41		 * Webpack fragments a wrapper builder reads, keyed by the path the workspace
42		 * writes for them. A fragment a target references but that is not supplied
43		 * here is reported unread and its wrapper builder is left in place.
44		 */
45		webpackFragments?: readonly WorkspaceFile[];
46	}>;
47	
48	export type MigratedFile = Readonly<{
49		path: string;
50		kind: 'application' | 'workspace';
51		changed: boolean;
52		sha256Before: string;
53		sha256After: string;
54		source: string;
55		changes: readonly string[];
56	}>;
57	
58	export type AngularMigration = Readonly<{
59		cell: string;
60		files: readonly MigratedFile[];
61		applicationFilesChanged: number;
62		workspaceFilesChanged: number;
63		applicationFilesScanned: number;
64		unhandled: readonly string[];
65	}>;
66	
67	function sha256(value: string): string {
68		return createHash('sha256').update(value).digest('hex');
69	}
70	
71	function describeConfigChange(change: ConfigChange): string {
72		if (change.to === null) return `removed ${change.path} (was ${change.from ?? 'absent'})`;
73		if (change.from === null) return `added ${change.path} = ${change.to}`;
74		return `${change.path}: ${change.from} -> ${change.to}`;
75	}
76	
77	function describeDependencyChange(change: DependencyChange): string {
78		const target = `${change.field}.${change.name}`;
79		return change.to === null
80			? `removed ${target} (was ${change.from}) — ${change.reason}`
81			: `${target}: ${change.from} -> ${change.to} — ${change.reason}`;
82	}
83	
84	function describeSourceChange(change: SourceChange | NgrxEffectChange): string {
85		return `line ${change.line}: ${change.kind} ${change.from} -> ${change.to}`;
86	}
87	
88	function file(
89		input: WorkspaceFile,
90		source: string,
91		kind: MigratedFile['kind'],
92		changes: readonly string[],
93	): MigratedFile {
94		return Object.freeze({
95			path: input.path,
96			kind,
97			changed: source !== input.source,
98			sha256Before: sha256(input.source),
99			sha256After: sha256(source),
