		fact: '7.0.0 is the newest release and declares peer @angular/core ">= 13.0.0", satisfied by this cell. The 6.x line the era workspace carried declares no @angular peer.',
	}),
	'@ngneat/until-destroy': Object.freeze({
		kind: 'aligned',
		range: '^10.0.0',
